const out = [];
const microQ = [];
const enqueue = (fn) => microQ.push(fn); // a microtask is a job on this queue
out.push('sync');
// Promise.resolve().then(3a).then(3b): 3a is enqueued now; 3b is enqueued only
// when 3a runs — re-entering the SAME drain, after anything already queued.
enqueue(() => { out.push('3a'); enqueue(() => out.push('3b')); });
// queueMicrotask(3c): enqueued now, so it sits behind 3a but ahead of 3b.
enqueue(() => out.push('3c'));
// Drain the whole queue (re-entrant): 3a, then 3c, then the re-entered 3b.
while (microQ.length) microQ.shift()();
console.log(out.join(' '));
